import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Filter for the "Thalamus in the middle" project
filter = {"data_description.project_name": "Thalamus in the middle"}

# Project only the targeted structures and name fields
projection = {
    "procedures.subject_procedures.procedures.targeted_structure": 1,
    "name": 1
}

records = docdb_api_client.retrieve_docdb_records(
    filter_query=filter,
    projection=projection,
)

# Extract and display unique targeted structures
targeted_structures = set()
for record in records:
    if "procedures" in record and "subject_procedures" in record["procedures"]:
        for subject_proc in record["procedures"]["subject_procedures"]:
            if "procedures" in subject_proc:
                for procedure in subject_proc["procedures"]:
                    if "targeted_structure" in procedure and procedure["targeted_structure"] is not None:
                        targeted_structures.add(procedure["targeted_structure"])

print("Brain structures data was collected from in the 'Thalamus in the middle' project:")
if targeted_structures:
    for structure in sorted(list(targeted_structures)):
        print(f"- {structure}")
else:
    print("No targeted structures found in the records.")

print("\nTotal number of unique targeted structures:", len(targeted_structures))

