predicted_answer:
import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Aggregation pipeline to find animals in "Thalamus in the middle" project
# with injections at coordinates AP: 2.8, ML: 0.2, DV: 0.6
agg_pipeline = [
    {
        "$match": {
            "data_description.project_name": "Thalamus in the middle",
            "procedures.subject_procedures": {
                "$elemMatch": {
                    "procedures": {
                        "$elemMatch": {
                            "procedure_type": {"$regex": "injection", "$options": "i"},
                            "injection_coordinate_ap": "2.8",
                            "injection_coordinate_ml": "0.2",
                            "injection_coordinate_depth": {"$in": ["0.6"]}
                        }
                    }
                }
            }
        }
    },
    {
        "$project": {
            "_id": 1,
            "name": 1,
            "data_description.project_name": 1,
            "subject.subject_id": 1,
            "procedures.subject_id": 1,
            "procedures.subject_procedures.procedures": {
                "$filter": {
                    "input": "$procedures.subject_procedures.procedures",
                    "as": "proc",
                    "cond": {
                        "$and": [
                            {"$eq": ["$$proc.injection_coordinate_ap", "2.8"]},
                            {"$eq": ["$$proc.injection_coordinate_ml", "0.2"]},
                            {"$in": ["0.6", "$$proc.injection_coordinate_depth"]}
                        ]
                    }
                }
            }
        }
    },
    {
        "$group": {
            "_id": None,
            "count": {"$sum": 1},
            "subjects": {"$addToSet": "$subject.subject_id"}
        }
    },
    {
        "$project": {
            "_id": 0,
            "count": 1,
            "subjects": 1,
            "unique_subject_count": {"$size": "$subjects"}
        }
    }
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)
print(json.dumps(result, indent=3))

