import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Filter for mice in "Thalamus in the middle" project with injections in VM
filter = {
    "data_description.project_name": "Thalamus in the middle",
    "procedures.subject_procedures.procedures.targeted_structure": "VM"
}

# Project only the subject ID and virus names
projection = {
    "subject.subject_id": 1,
    "procedures.subject_procedures.procedures.injection_materials.name": 1
}

records = docdb_api_client.retrieve_docdb_records(
    filter_query=filter,
    projection=projection,
)

# Process the results to create a clean list of unique subject IDs and their virus injections
subject_virus_map = {}

for record in records:
    subject_id = record["subject"]["subject_id"]

    if subject_id not in subject_virus_map:
        subject_virus_map[subject_id] = set()

    # Extract all virus names from the procedures
    for procedure_group in record["procedures"]["subject_procedures"]:
        if "procedures" in procedure_group:
            for procedure in procedure_group["procedures"]:
                if "injection_materials" in procedure:
                    for material in procedure["injection_materials"]:
                        if "name" in material:
                            subject_virus_map[subject_id].add(material["name"])

# Convert sets to lists for JSON serialization
result = []
for subject_id, viruses in sorted(subject_virus_map.items()):
    result.append({
        "subject_id": subject_id,
        "virus_names": sorted(list(viruses))
    })

print(json.dumps(result, indent=2))

