docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# First, find all fiber photometry experiments
fiber_photometry_filter = {
    "$or": [
        {"data_description.modality": "fiber_photometry"},
        {"rig.modalities": "fiber_photometry"},
        {"session.data_streams.modality": "fiber_photometry"}
    ]
}

fiber_photometry_records = docdb_api_client.retrieve_docdb_records(
    filter_query=fiber_photometry_filter,
    projection={"_id": 1}
)

total_fiber_photometry = len(fiber_photometry_records)

# Now find fiber photometry experiments with behavioral data
behavioral_and_fiber_filter = {
    "$and": [
        {
            "$or": [
                {"data_description.modality": "fiber_photometry"},
                {"rig.modalities": "fiber_photometry"},
                {"session.data_streams.modality": "fiber_photometry"}
            ]
        },
        {
            "$or": [
                {"session.data_streams.modality": "behavior"},
                {"data_description.modality": "behavior"},
                {"session.data_streams.device_name": {"$regex": "camera", "$options": "i"}},
                {"session.data_streams.device_name": {"$regex": "video", "$options": "i"}}
            ]
        }
    ]
}

behavioral_fiber_records = docdb_api_client.retrieve_docdb_records(
    filter_query=behavioral_and_fiber_filter,
    projection={"_id": 1}
)

with_behavioral_data = len(behavioral_fiber_records)

if total_fiber_photometry > 0:
