COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Aggregation pipeline to find assets where procedure dates occurred before subject's date of birth
agg_pipeline = [
    # Match documents that have both procedures and subject date of birth
    {
        "$match": {
            "procedures": {"$exists": True},
            "subject": {"$exists": True},
            "subject.date_of_birth": {"$exists": True}
        }
    },
    # Project relevant fields
    {
        "$project": {
            "name": 1,
            "subject_id": "$subject.subject_id",
            "date_of_birth": "$subject.date_of_birth",
            "subject_procedures": "$procedures.subject_procedures"
        }
    },
    # Unwind the procedures array to compare each procedure individually
    {
        "$unwind": "$subject_procedures"
    },
    # Only include procedures with valid start dates (not null)
    {
        "$match": {
            "subject_procedures.start_date": {"$ne": None}
        }
    },
    # Project fields and add a flag for procedures before birth
    {
        "$project": {
            "name": 1,
            "subject_id": 1,
            "date_of_birth": 1,
            "procedure_type": "$subject_procedures.procedure_type",
            "procedure_date": "$subject_procedures.start_date",
            "is_before_birth": {"$lt": ["$subject_procedures.start_date", "$date_of_birth"]}
        }
    },
    # Filter to only include procedures that occurred before birth
    {
        "$match": {
            "is_before_birth": True
        }
    },
    # Group by asset to avoid duplicates
    {
        "$group": {
            "_id": "$_id",
            "name": {"$first": "$name"},
            "subject_id": {"$first": "$subject_id"},
            "date_of_birth": {"$first": "$date_of_birth"},
            "procedure_types": {"$addToSet": "$procedure_type"},
            "procedure_dates": {"$addToSet": "$procedure_date"}
        }
    },
    # Limit results to 20 for readability
    {
        "$limit": 20
    }
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)
print(json.dumps(result, indent=3))

