import json

from aind_data_access_api.document_db import MetadataDbClient

API_GATEWAY_HOST = "api.allenneuraldynamics-test.org"
DATABASE = "metadata_vector_index"
COLLECTION = "static_eval_data_assets_3_14"

docdb_api_client = MetadataDbClient(
    host=API_GATEWAY_HOST,
    database=DATABASE,
    collection=COLLECTION,
)

# Create an aggregation pipeline to find Ai224 animals and count their injections
agg_pipeline = [
    # Match documents with Ai224 genotype and that have procedures
    {"$match": {
        "subject.genotype": {"$regex": "Ai224", "$options": "i"},
        "procedures.subject_procedures": {"$exists": True}
    }},
    # Unwind the procedures array to count individual procedures
    {"$unwind": "$procedures.subject_procedures"},
    # Count the total number of procedures (injections)
    {"$count": "total_injections"}
]

result = docdb_api_client.aggregate_docdb_records(
    pipeline=agg_pipeline
)

print(json.dumps(result, indent=3))

# If we want to see the details of each injection for verification
detail_pipeline = [
    {"$match": {
        "subject.genotype": {"$regex": "Ai224", "$options": "i"},
        "procedures.subject_procedures": {"$exists": True}
    }},
    {"$project": {
        "subject_id": "$subject.subject_id",
        "genotype": "$subject.genotype",
        "procedures": "$procedures.subject_procedures"
    }}
]

detailed_result = docdb_api_client.aggregate_docdb_records(
    pipeline=detail_pipeline
)

print(f"\nDetails of injections in Ai224 animals (first 3 records):")
